const raw = $input.first().json;
let parsed;
let aiParseError = false;
let aiParseErrorMessage = '';

try {
  const text = raw.candidates[0].content.parts[0].text;
  parsed = JSON.parse(text);
  if (!parsed || typeof parsed.score !== 'number' || !parsed.recommendation || !parsed.riskLevel) {
    throw new Error('AI response missing required fields');
  }
} catch (err) {
  aiParseError = true;
  aiParseErrorMessage = err.message;
  // Safe fallback: force this application into the human Manual Review lane
  // rather than silently mis-routing it or crashing the workflow.
  parsed = {
    skills: [],
    yearsExperience: null,
    education: 'Unknown',
    pastEmployers: [],
    score: null,
    recommendation: 'Review',
    summary: 'AI evaluation could not be parsed automatically. Manual review required.',
    riskLevel: 'High',
    flags: ['AI parsing failed - manual review required: ' + aiParseErrorMessage]
  };
}

const form = $('When Form Submitted').item.json;
const appId = $('Set Application ID and Date').item.json.applicationId;
const submittedAt = $('Set Application ID and Date').item.json.submittedAt;

return [{
  json: {
    applicationId: appId,
    submittedAt: submittedAt,
    name: form['Full Name'],
    email: form['Email'],
    linkedin: form['Portfolio / LinkedIn'],
    skills: (parsed.skills || []).join(', '),
    yearsExperience: parsed.yearsExperience,
    education: parsed.education,
    pastEmployers: (parsed.pastEmployers || []).join(', '),
    score: parsed.score,
    recommendation: parsed.recommendation,
    summary: parsed.summary,
    riskLevel: parsed.riskLevel,
    flags: (parsed.flags || []).join('; '),
    aiParseError: aiParseError
  }
}];

